//DS | catalog.проект_заказ | id ($h.площадка ) | Select (id, префикс) | Value ( префикс )

async function getCatalogValue(catalogName, id, fieldName) {
  var table = await from(catalogName)
    .select([fieldName])
    .where('id = @id')
    .parameter('id', id)
    .query();

  var value = null;

  if ((table.rows ?? []).length > 0) {
    value = table.rows[0][fieldName];
  }

  return value;
};
var result = await getCatalogValue(
  'catalog.проект_заказ',
  $h.площадка,
  'префикс'
);

return result;

